#!/usr/bin/env bash
# SPDX-License-Identifier: AGPL-3.0-or-later
set -euo pipefail
source "$(dirname "$0")/common.sh"; cd "$HERE"; require_ros; require_proxy
for seed in $SEEDS; do
  src="$RESULTS_ROOT/main/mcpilot_complete/$seed"; [[ -s "$src/delay_compensation_config.json" ]] || { echo "Run run_mcpilot.sh first"; exit 1; }
  read base_ant base_width < <(source_delay "$src")
  for particles in 50 200; do out="$RESULTS_ROOT/ablations/particles/$particles/$seed"; mkdir -p "$out"; copy_cache "$src" "$out" 5; set_full_delay "$seed" "$base_ant"; "$PYTHON_BIN" -u test_mcpilcoros_tossing_with_panda_rbf_ker.py -seed "$seed" -device_name "$DEVICE" -num_particles "$particles" -model Speed -target_radius .05 -num_exp 5 -num_trials 1 -num_toss_test 30 -num_test_trials 1 -flg_do_test True -evaluation_seed "$EVAL_SEED" -release_anticipation_seconds "$base_ant" -physical_delay_lower_seconds .12 -physical_delay_upper_seconds .13 -synthetic_ground_truth True -bullet_name red_ball_friction -flg_model_release_delay True -flg_apply_release_anticipation True -manual_delay_lower_seconds 0 -manual_delay_upper_seconds "$base_width" -flg_use_cache True -flg_compensate_release_radial_velocity True -policy_optimization_seed "$seed" -run_output_dir "$out"; done
  out="$RESULTS_ROOT/ablations/gp_sampling/predictive_mean/$seed"; mkdir -p "$out"; copy_cache "$src" "$out" 5; set_full_delay "$seed" "$base_ant"; "$PYTHON_BIN" -u test_mcpilcoros_tossing_with_panda_rbf_ker.py -seed "$seed" -device_name "$DEVICE" -num_particles 400 -model Speed -target_radius .05 -num_exp 5 -num_trials 1 -num_toss_test 30 -num_test_trials 1 -flg_do_test True -evaluation_seed "$EVAL_SEED" -release_anticipation_seconds "$base_ant" -physical_delay_lower_seconds .12 -physical_delay_upper_seconds .13 -synthetic_ground_truth True -bullet_name red_ball_friction -flg_model_release_delay True -flg_apply_release_anticipation True -manual_delay_lower_seconds 0 -manual_delay_upper_seconds "$base_width" -flg_use_cache True -flg_compensate_release_radial_velocity True -flg_sample_gp_posterior False -policy_optimization_seed "$seed" -run_output_dir "$out"
  for spec in 60:70 90:100 110:120 120:130 130:140 150:160; do L=${spec%:*}; U=${spec#*:}; ant=$(awk "BEGIN{print $L/1000}"); width=$(awk "BEGIN{print ($U-$L)/1000}"); out="$RESULTS_ROOT/ablations/effective_delay/${L}_${U}_ms/$seed"; mkdir -p "$out"; copy_cache "$src" "$out" 5; set_full_delay "$seed" "$ant"; "$PYTHON_BIN" -u test_mcpilcoros_tossing_with_panda_rbf_ker.py -seed "$seed" -device_name "$DEVICE" -num_particles 400 -model Speed -target_radius .05 -num_exp 5 -num_trials 1 -num_toss_test 30 -num_test_trials 1 -flg_do_test True -evaluation_seed "$EVAL_SEED" -release_anticipation_seconds "$ant" -physical_delay_lower_seconds .12 -physical_delay_upper_seconds .13 -synthetic_ground_truth True -bullet_name red_ball_friction -flg_model_release_delay True -flg_apply_release_anticipation True -manual_delay_lower_seconds 0 -manual_delay_upper_seconds "$width" -manual_delay_source full_effective_delay_ablation -flg_use_cache True -flg_compensate_release_radial_velocity True -policy_optimization_seed "$seed" -run_output_dir "$out"; done
  for pair in two:0 six:2; do label=${pair%:*}; copies=${pair#*:}; out="$RESULTS_ROOT/ablations/data_augmentation/$label/$seed"; mkdir -p "$out"; copy_cache "$src" "$out" 2; set_full_delay "$seed" "$base_ant"; "$PYTHON_BIN" -u test_mcpilcoros_tossing_with_panda_rbf_ker.py -seed "$seed" -device_name "$DEVICE" -num_particles 400 -model Speed -target_radius .05 -num_exp 2 -num_trials 1 -num_toss_test 30 -num_test_trials 1 -flg_do_test True -evaluation_seed "$EVAL_SEED" -release_anticipation_seconds "$base_ant" -physical_delay_lower_seconds .12 -physical_delay_upper_seconds .13 -synthetic_ground_truth True -bullet_name red_ball_friction -flg_model_release_delay True -flg_apply_release_anticipation True -manual_delay_lower_seconds 0 -manual_delay_upper_seconds "$base_width" -flg_use_cache True -flg_compensate_release_radial_velocity True -data_augmentation "$copies" -data_augmentation_max_angle_degrees 45 -std_meas_noise 0.01 -std_velocity_meas_noise 0 -flg_apply_meas_noise_to_training_data True -flg_real_style_data_augmentation True -training_measurement_noise_seed "$seed" -policy_optimization_seed "$seed" -run_output_dir "$out"; done
done
